const CHAVE_CADASTRO='ongEsperancaCadastro';function salvarCadastro(dados){localStorage.setItem(CHAVE_CADASTRO,JSON.stringify(dados));}function recuperarCadastro(){const dados=localStorage.getItem(CHAVE_CADASTRO);return dados?JSON.parse(dados):null;}function limparCadastro(){localStorage.removeItem(CHAVE_CADASTRO);}let inicializado=false;function ehRotaInterna(link){if(!link || link.target==='_blank' || link.hasAttribute('download'))return false;if(link.origin !==window.location.origin)return false;return /\.html$/i.test(new URL(link.href).pathname);}async function carregarPagina(url,adicionarHistorico=true){const destino=new URL(url,window.location.href);const app=document.querySelector('#app');if(!app)return;app.setAttribute('aria-busy','true');app.innerHTML='<p role="status">Carregando página...</p>';try{const resposta=await fetch(destino.href);if(!resposta.ok)throw new Error('Página não encontrada.');const html=await resposta.text();const documento=new DOMParser().parseFromString(html,'text/html');const novoApp=documento.querySelector('#app');if(!novoApp)throw new Error('Área da aplicação não encontrada.');app.innerHTML=novoApp.innerHTML;app.setAttribute('aria-busy','false');if(adicionarHistorico)history.pushState({},'',destino.href);document.title=documento.title || document.title;window.scrollTo({top:0,behavior:'smooth'});window.dispatchEvent(new CustomEvent('spa:page-loaded'));}catch(erro){app.setAttribute('aria-busy','false');app.innerHTML=`<div class="alert alert-error" role="alert"><strong>Não foi possível carregar a página.</strong><p>${erro.message}</p></div>`;}}function initRouter(){if(inicializado)return;inicializado=true;document.addEventListener('click',event=>{const link=event.target.closest('a');if(!ehRotaInterna(link))return;event.preventDefault();carregarPagina(link.href);});window.addEventListener('popstate',()=>carregarPagina(window.location.href,false));}const projetos=[{titulo:'Campanhas de arrecadação',categoria:'Doação',classe:'badge-doacao',descricao:'Arrecadação de alimentos,roupas e materiais para famílias atendidas.'},{titulo:'Apoio à comunidade',categoria:'Comunidade',classe:'badge-comunidade',descricao:'Ações voltadas à inclusão,cidadania e melhoria da qualidade de vida.'},{titulo:'Ações educativas',categoria:'Voluntariado',classe:'badge-voluntariado',descricao:'Atividades educativas e de conscientização com participação voluntária.'}];function renderProjetos(){const container=document.querySelector('#lista-projetos');if(!container)return;container.innerHTML=projetos.map(projeto=>`<article><span class="badge ${projeto.classe}">${projeto.categoria}</span><h3>${projeto.titulo}</h3><p>${projeto.descricao}</p></article>`).join('');}function initProjetos(){renderProjetos();window.addEventListener('spa:page-loaded',renderProjetos);}function mostrarMensagem(campo,mensagem,tipo='erro'){const grupo=campo.closest('.campo')|| campo.parentElement;let aviso=grupo.querySelector('.mensagem-validacao');if(!aviso){aviso=document.createElement('small');aviso.className='mensagem-validacao';aviso.id=`aviso-${campo.id || campo.name}`;aviso.setAttribute('role','alert');grupo.appendChild(aviso);}aviso.textContent=mensagem;aviso.hidden=!mensagem;aviso.classList.toggle('mensagem-erro',tipo==='erro');aviso.classList.toggle('mensagem-sucesso',tipo==='sucesso');if(mensagem)campo.setAttribute('aria-describedby',aviso.id);else campo.removeAttribute('aria-describedby');campo.setAttribute('aria-invalid',tipo==='erro' && Boolean(mensagem)?'true':'false');campo.classList.toggle('campo-invalido',tipo==='erro' && Boolean(mensagem));campo.classList.toggle('campo-valido',tipo==='sucesso' && Boolean(mensagem));}function validarCampo(campo){if(!campo || campo.disabled || campo.type==='checkbox')return true;if(!campo.value.trim()&& campo.required){mostrarMensagem(campo,'Este campo é obrigatório.');return false;}if(campo.value && !campo.checkValidity()){mostrarMensagem(campo,campo.validationMessage || 'Verifique o formato informado.');return false;}if(campo.value)mostrarMensagem(campo,'Preenchimento válido.','sucesso');else mostrarMensagem(campo,'');return true;}function validarFormulario(formulario){let valido=true;formulario.querySelectorAll('input,select,textarea').forEach(campo=>{if(!validarCampo(campo))valido=false;});return valido && formulario.checkValidity();}function coletarDados(formulario){const dados=Object.fromEntries(new FormData(formulario).entries());dados.interesses=[...formulario.querySelectorAll('input[name="interesses"]:checked')].map(campo=>campo.value);return dados;}function preencherFormulario(dados){if(!dados)return;Object.entries(dados).forEach(([nome,valor])=>{document.querySelectorAll(`[name="${nome}"]`).forEach(campo=>{if(campo.type==='checkbox')campo.checked=Array.isArray(valor)&& valor.includes(campo.value);else if(campo.type==='radio')campo.checked=campo.value===valor;else campo.value=valor;});});}function abrirModal(){const modal=document.querySelector('#confirmacao');if(modal?.showModal)modal.showModal();}function initFormulario(){const restaurarDados=()=>preencherFormulario(recuperarCadastro());restaurarDados();window.addEventListener('spa:page-loaded',restaurarDados);document.addEventListener('input',event=>{const campo=event.target.closest('#form-cadastro input,#form-cadastro select,#form-cadastro textarea');if(campo)validarCampo(campo);});document.addEventListener('blur',event=>{const campo=event.target.closest('#form-cadastro input,#form-cadastro select,#form-cadastro textarea');if(campo)validarCampo(campo);},true);document.addEventListener('submit',event=>{const formulario=event.target.closest('#form-cadastro');if(!formulario)return;event.preventDefault();if(!validarFormulario(formulario)){formulario.querySelector(':invalid')?.focus();return;}salvarCadastro(coletarDados(formulario));abrirModal();});}function initMenu(){const botao=document.querySelector('#menu-toggle');const menu=document.querySelector('#menu-principal');if(!botao || !menu)return;botao.addEventListener('click',()=>{const aberto=botao.getAttribute('aria-expanded')==='true';botao.setAttribute('aria-expanded',String(!aberto));botao.setAttribute('aria-label',aberto?'Abrir menu':'Fechar menu');menu.classList.toggle('menu-aberto',!aberto);});menu.addEventListener('click',event=>{if(event.target.closest('a')){botao.setAttribute('aria-expanded','false');botao.setAttribute('aria-label','Abrir menu');menu.classList.remove('menu-aberto');}});}document.addEventListener('DOMContentLoaded',()=>{initRouter();initFormulario();initProjetos();initMenu();window.addEventListener('spa:page-loaded',()=>{const titulo=document.querySelector('#app h1');titulo?.setAttribute('tabindex','-1');titulo?.focus({preventScroll:true});});});